(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0010.js"] = [{"id":"glyph-kai-80da","script":"kai","character":"胚","reading":"pēi","description":"pēi：初期发育的生物体～芽。～囊。～胎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胚"},{"id":"glyph-kai-80dc","script":"kai","character":"胜","reading":"shèng","description":"言讫,?\n战胜,打败\n胜,克\n⒈赢，跟\"败\"、\"负\"相对～利。～仗。～不骄。\n⒊超过～过。～似。～于。略～一筹。\n⒋优美的，盛大的～地。～景。～会。\n①能担当得起或承受得住～任愉快。不～其烦。\n②尽不可～数。\n③又叫\"肽\"。见肽。\n胜xīng 1.同\"腥\"。 2.瘦。参见\"膌胜\"。\n胜qìng 1.见\"胜遇\"。\n胜shèng 1.能够承受，禁得起。 2.尽。 3.陵，欺凌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胜"},{"id":"glyph-kai-80de","script":"kai","character":"胞","reading":"bāo","description":"bāo：同一父母所生的～兄。～妹。同～（ａ．同父母所生的；ｂ．同一个国家或民族的人）。～波（缅语同胞和亲戚的意思，缅甸人习惯用来称呼中国人，以表示亲切）。\n〔细～〕生物体的基本结构和功能单位，主要由细胞核、细胞质、细胞膜等构成，有运动、营养和繁殖等机能。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胞"},{"id":"glyph-kai-80e1","script":"kai","character":"胡","reading":"hú","description":"鸟兽颔下的垂肉或皮囊\n器物上下垂如胡的部分\n古代称北方和西方的民族如匈奴等为胡\n⒈〈古〉我国西北地区的民族之统称～人。～服。泛指我国少数民族的或外国的～椒。～琴。～萝卜。\n⒊文言疑问代词。什么，怎样～为慕大鲸？～不归？\n⒋〈古〉指兽颈下的垂肉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胡"},{"id":"glyph-kai-80e7","script":"kai","character":"胧","reading":"lóng","description":"胧lǒng 1.见\"胧肿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胧"},{"id":"glyph-kai-80f0","script":"kai","character":"胰","reading":"yí","description":"yí：人或高等动物体内的腺体之一，在胃的后下方（亦称胰腺”）～液。～脂酶。～蛋白酶。～淀粉酶。～子（ａ．猪羊等的胰；ｂ．肥皂）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胰"},{"id":"glyph-kai-80f3","script":"kai","character":"胳","reading":"gē；gé","description":"gē：〔～臂〕上肢，肩膀以下手腕以上的部分。亦称胳膊”（臂”、膊”均读轻声）。\n〔～肢窝〕同夹肢窝”。\ngé：同骼”。\n〔～肢〕在别人身上抓挠，使人由发痒而笑（肢”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胳"},{"id":"glyph-kai-80f6","script":"kai","character":"胶","reading":"jiāo","description":"古代大学之称,后泛指学校\n鸡鸣声,泛指禽类鸣声\n⒈粘性物质。用动物皮、角或树脂等制成。也有人工合成的牛皮～。树脂～。万能～。\n⒉制成胶质的药品阿～。鹿角～。\n⒊特指橡胶～轮。～底鞋。\n⒋像胶那样有粘性的～泥。～水。\n⒌粘住，粘合～着。～合。\n胶jiǎo 1.见\"胶胶扰扰\"。\n胶háo 1.戾。参见\"胶加\"﹑\"胶戾\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胶"},{"id":"glyph-kai-80f8","script":"kai","character":"胸","reading":"xiōng","description":"xiōng：身体前面颈下腹上的部分，借指心里～脯。～膛。～腔。～口。～骨。～椎。～膜。～怀（抱负、气量）。～襟（同胸怀”）。～无点墨（指读书太少，文化水平极低）。直抒～臆。～中有数（shù）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胸"},{"id":"glyph-kai-80fd","script":"kai","character":"能","reading":"néng；nài","description":"néng：(1)才干，本事～力。～耐。才～。\n(2)有才干的～人。～手。贤～。～工巧匠。～者为师。\n(3)胜任，善于～够。～柔～刚。力所～及。欲罢不～。～动。\n(4)会（表示可能性）小弟弟～走路了。\n(5)应该你不～这样说他。\n(6)物理学名词，能量”的简称电～。热～。\n(7)和睦（萧）何素不与曹参相～”。\n(8)传说中的一种兽，似熊。\n(9)古代称一种三足鳖。\nnài：古同耐”，受得住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-能"},{"id":"glyph-kai-8102","script":"kai","character":"脂","reading":"zhī","description":"zhī：(1)动物体内或油料植物种子内的油质～肪。～膏。松～。～油。香～。\n(2)指胭脂”～粉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脂"},{"id":"glyph-kai-8106","script":"kai","character":"脆","reading":"cuì","description":"cuì：(1)容易断，容易碎的～性。～枣。～骨。青～爽口。～生生。～弱。\n(2)声音清爽（高音）～亮。～美。清～悦耳。\n(3)说话做事爽利痛快干～。办事很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脆"},{"id":"glyph-kai-8109","script":"kai","character":"脉","reading":"mài","description":"mài：(1)分布在人和动物周身内的血管～络。～理。\n(2)动脉的跳动～搏。切～（中医指诊脉）。～口（中医切脉的部位）。～息。～象（指脉搏的形象与动态）。～门（手腕部可以看到的桡动脉跳动的部分）。诊～。\n(3)像血管那样连贯而自成系统的东西山～。叶～。矿～。～～相承。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脉"},{"id":"glyph-kai-810a","script":"kai","character":"脊","reading":"jǐ","description":"jǐ：(1)人和动物背上中间的骨头～椎。～髓。～柱。～梁。～背。～椎动物。\n(2)中间高起的部分山～。屋～。书～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脊"},{"id":"glyph-kai-810f","script":"kai","character":"脏","reading":"zāng","description":"脏zǎng 1.见\"骯脏\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脏"},{"id":"glyph-kai-8110","script":"kai","character":"脐","reading":"qí","description":"螃蟹腹部的厣,雌者圆形称团脐”,雄者尖形称尖脐”\n某些物体中央凹凸处状如脐\n⒉螃蟹腹部的甲壳，雄尖雌圆，故有尖～、圆～之称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脐"},{"id":"glyph-kai-8111","script":"kai","character":"脑","reading":"nǎo","description":"形状或颜色像脑髓的东西\n头部\n官开动～筋。用～子，好好想想。\n⒉形状或颜色像脑的豆腐～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脑"},{"id":"glyph-kai-8113","script":"kai","character":"脓","reading":"nóng","description":"腐烂\n肥硕\n同醲”。浓厚。特指浓烈的酒","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脓"},{"id":"glyph-kai-8116","script":"kai","character":"脖","reading":"bó","description":"bó：(1)颈，头和躯干相连的部分～子。～颈。～梗儿。\n(2)像脖子的脚～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脖"},{"id":"glyph-kai-811a","script":"kai","character":"脚","reading":"jiǎo","description":"jiǎo：(1)人和某些动物身体最下部接触地面的部分～心。～掌。～背。～跟。～步。～印。～法（指踢球、踢毽等的技巧）。～镣。～踏实地（形容做事实事求是，不浮夸）。\n(2)最下部～注。山～。墙～。\n(3)剩下的废料，渣滓下～料。\n(4)旧时指与体力搬运有关的～夫。～行（háng）。～钱。拉～。\n〔～本〕表演戏剧或拍摄影视所依据的底本。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脚"},{"id":"glyph-kai-812f","script":"kai","character":"脯","reading":"pú；fǔ","description":"fǔ：(1)肉干鹿～。兔～。\n(2)水果蜜渍后晾干的成品果～。杏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脯"},{"id":"glyph-kai-8131","script":"kai","character":"脱","reading":"tuō","description":"tuō：(1)离开，落掉～产。～发（fà）。～节。～离。～落。～贫（摆脱贫困）。～稿（完成著作）。～手。摆～。挣～。临阵逃～。\n(2)遗漏～漏。～误。～文（因抄刊古书而误脱的字。亦称夺文”）。\n(3)取下，除去～下。～帽。～氧。～脂。～胎换骨。\n(4)倘若，或许～有不测。\n(5)轻慢～略（放任，不拘束）。～易（轻率，不讲究礼貌）。轻～（轻率，不持重，放荡）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脱"},{"id":"glyph-kai-8138","script":"kai","character":"脸","reading":"liǎn","description":"脸面,人头的前部,包括下巴、嘴、鼻、颊、眼,且通常包括前额\n你看你的脸…尽是血,我都不\n⒈面孔，头前部由额到下巴～形。～庞儿。〈引〉\n①体面，面子丢～。\n②物体的上部或前部桌～儿。鞋子～儿。柜子～儿。门～儿。\n⒉脸的表情笑～。变了～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脸"},{"id":"glyph-kai-813e","script":"kai","character":"脾","reading":"pí","description":"pí：(1)人和动物内脏之一，在胃的左下侧，是重要的贮藏血液的器官和最大的淋巴器官～脏。\n(2)中医学指五脏之一～胃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脾"},{"id":"glyph-kai-814a","script":"kai","character":"腊","reading":"là","description":"农历十二月\n腊后花期知渐近,寒梅已作东风信\n⒈干肉，将肉晾干。\n腊liè 1.剑的两面刃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腊"},{"id":"glyph-kai-814b","script":"kai","character":"腋","reading":"yè","description":"yè：(1)胳肢窝，上肢同肩膀相连处靠里凹入的部分～窝。～下。集～成裘。\n(2)其他生物体上与腋类似的部分～芽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腋"},{"id":"glyph-kai-8150","script":"kai","character":"腐","reading":"fǔ","description":"fǔ：(1)朽烂，变质～烂。～朽。～败。～化。～蚀。～臭。陈～。流水不～。\n(2)思想陈旧过时～旧。～儒。迂～。\n(3)某些豆制食品豆～（腐”读轻声）。～乳。～竹。\n(4)古代指施以宫刑～刑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腐"},{"id":"glyph-kai-8154","script":"kai","character":"腔","reading":"qiāng","description":"qiāng：(1)动物身体中空的部分～子。体～。满～热血。\n(2)器物的中空部分炉～。\n(3)乐曲的调子～调（diào）。唱～。梆子～。\n(4)说话的声音、语调开～。京～。装～作势。拿～拿调。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腔"},{"id":"glyph-kai-8155","script":"kai","character":"腕","reading":"wàn","description":"wàn：胳膊下端与手掌相连的部分手～。～骨。～力。扼～（表示惋惜等情绪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腕"},{"id":"glyph-kai-8165","script":"kai","character":"腥","reading":"xīng","description":"xīng：(1)像鱼的气味～气。血～。～膻。～秽。～臭。～臊。～风血雨。\n(2)鱼或肉一类的食品荤～。\n(3)生肉君赐～，必熟而蔫之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腥"},{"id":"glyph-kai-816e","script":"kai","character":"腮","reading":"sāi","description":"sāi：面颊的下半部，脸的两旁（亦称腮帮子”）～颊。～腺（两耳下部的唾液腺）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腮"},{"id":"glyph-kai-8170","script":"kai","character":"腰","reading":"yāo","description":"yāo：(1)胯上胁下的部分，在身体的中部～板儿。～杆子。～背。～身。～肢。～围。\n(2)东西的中段，中间半山～。\n(3)中间狭小像腰部的地势土～。～。\n(4)裤、裙等围在腰上的部分裤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腰"},{"id":"glyph-kai-8179","script":"kai","character":"腹","reading":"fù","description":"fù：(1)一般指人和脊椎动物躯干的一部分，介于胸和骨盆之间，包括腹壁”、腹腔”及内脏（通常称肚子”）～部。～膜。～水。～泻。～疾。心～（喻极亲近的人）。～稿。～诽（指口里不说而心里不以为然。亦作腹非”）。遗～子。\n(2)喻地区的前部、内部或中部～地。～背受敌。\n(3)厚（冬季之月）冰方盛，水泽～坚，命取冰。”\n(4)怀抱出入～我。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腹"},{"id":"glyph-kai-817a","script":"kai","character":"腺","reading":"xiàn","description":"xiàn：生物体内能分泌某些液汁的组织，由腺细胞组成，根据腺的生理机能及其是否具排出管，可分为外分泌腺”和内分泌腺”汗～。泪～。唾液～。花的蜜～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腺"},{"id":"glyph-kai-817b","script":"kai","character":"腻","reading":"nì","description":"粘糊\n亲昵\n细腻\n厌烦\n见了别\n⒈食品油脂过多油～。肥肉太多，～人。\n⒉滋润，光滑细～。滑～。\n⒊因过多而厌烦～烦。看～了。耍～了。\n⒋污垢尘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腻"},{"id":"glyph-kai-817e","script":"kai","character":"腾","reading":"téng","description":"奔驰\n跳跃\n⒈跳跃虎～。～跃。\n⒉奔驰奔～。\n⒊上升～空。飞～。\n⒋乘，骑～驴。\n⒌传，传递～书信。\n⒍使空出来～时间。～出一间房子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腾"},{"id":"glyph-kai-817f","script":"kai","character":"腿","reading":"tuǐ","description":"tuǐ：(1)下肢，在脚的上面，在膝上胯下的称大腿”，在膝下脚上的称小腿”。～脚。\n(2)器物上像腿的部分桌子～儿。\n(3)特指经盐腌、洗晒、晾挂等工序加工成的猪后腿火～。云～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腿"},{"id":"glyph-kai-8180","script":"kai","character":"膀","reading":"bǎng","description":"bǎng：(1)胳膊的上部靠肩的部分～臂。肩～。～阔腰圆。\n(2)鸟类和昆虫的飞行器官翅～。～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膀"},{"id":"glyph-kai-818a","script":"kai","character":"膊","reading":"bó","description":"bó：(1)上肢，近肩的部分胳～。赤～（光膀子）。\n(2)分裂尸体而曝之杀而～诸城上”。\n〔厚～〕厚切肉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膊"},{"id":"glyph-kai-818f","script":"kai","character":"膏","reading":"gāo；gào","description":"gāo：(1)肥，肥肉～粱（肥肉、细粮）。～腴。～沃。\n(2)脂油春雨如～。～泽（ａ．滋润作物的及时雨；ｂ．喻给予恩惠）。\n(3)中医指心尖脂肪，认为是药力达不到的部位病入～肓。\ngào：(1)把油抹在车轴或机械上～油。\n(2)把毛笔蘸上墨汁在砚台边上掭～笔。～墨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膏"},{"id":"glyph-kai-819b","script":"kai","character":"膛","reading":"táng","description":"táng：(1)体腔胸～。开～。\n(2)器物中空的部分炉～儿。枪～。～线（亦称来复线”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膛"},{"id":"glyph-kai-819c","script":"kai","character":"膜","reading":"mó","description":"mó：(1)动植物体内像薄皮的组织肋～。耳～。黏～。苇～。\n(2)像膜的薄皮牛奶表面结了一层薄～。\n〔～拜〕跪在地上高举双手虔诚地行礼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膜"},{"id":"glyph-kai-819d","script":"kai","character":"膝","reading":"xī","description":"xī：大腿和小腿相连的关节的前部～盖骨（亦称髌骨”）。护～。屈～。～眼。～下（子女幼时依偎于父母的膝下，因以膝下”表示幼年◇用作对父母的敬辞）。奴颜卑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膝"},{"id":"glyph-kai-81a8","script":"kai","character":"膨","reading":"péng","description":"péng：胀～胀。～大。～化。\n〔～脝〕肚子胀的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膨"},{"id":"glyph-kai-81c0","script":"kai","character":"臀","reading":"tún","description":"tún：屁股～部。丰～。～鳍。前后～尖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臀"},{"id":"glyph-kai-81c2","script":"kai","character":"臂","reading":"bì；bei","description":"bì：从肩到手腕的部分～力。～腕。～肘。左膀右～。助你一～之力。\nbei：〔胳～〕见胳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臂"},{"id":"glyph-kai-81ca","script":"kai","character":"臊","reading":"sào；sāo","description":"sāo：像尿或狐狸的气味～气。腥～↑～。\nsào：害羞害～。羞～。\n〔～气〕倒霉（气”读轻声）。\n〔～子〕方言，肉末或肉丁，如羊肉～～面”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臊"},{"id":"glyph-kai-81e3","script":"kai","character":"臣","reading":"chén","description":"chén：(1)君主时代的官吏，有时亦包括百姓～僚。～子。～服。君～。\n(2)官吏对君主的自称王必无人，～愿奉璧往使。”\n(3)古人谦称自己。\n(4)古代指男性奴隶～仆。～虏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臣"},{"id":"glyph-kai-81ea","script":"kai","character":"自","reading":"zì","description":"zì：(1)本人，己身～己。～家。～身。～白。～满。～诩。～馁。～重（zhòng）。～尊。～谦。～觉（jué）。～疚。～学。～圆其说。～惭形秽。～强不息。\n(2)从，由～从。～古以来。\n(3)当然～然。～不待言。～生～灭。放任～流。\n(4)假如～非圣人，外宁必有内忧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-自"},{"id":"glyph-kai-81ed","script":"kai","character":"臭","reading":"chòu；xiù","description":"chòu：(1)不好闻的气味，与香”相对～味儿。～氧。恶～。\n(2)香气左佩刀，右备容～，烨然若神人”。\n(3)惹人厌恶的～钱。～美。～架子。～名远扬。\n(4)狠狠地～骂一通。\n(5)指子弹、炮弹坏，失效～火。\n香；\nxiù：(1)气味的总称无声无～。\n(2)同嗅”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臭"},{"id":"glyph-kai-81f3","script":"kai","character":"至","reading":"zhì","description":"zhì：(1)到～此。自始～终。从古～今。～于。以～。甚～。\n(2)极、最～少。～亲。～交（最相好的朋友）。～诚。～高无上。～理名言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-至"},{"id":"glyph-kai-81f4","script":"kai","character":"致","reading":"zhì","description":"zhì：(1)送给，给予～仕（退休）。～辞。～电。～力。～哀。～命。\n(2)招引，使达到～病。～使。以～。专心～志。\n(3)意态，情况大～。别～。景～。兴（xìng）～。\n(4)细密，精细～密。精～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-致"},{"id":"glyph-kai-81fc","script":"kai","character":"臼","reading":"jiù","description":"jiù：(1)舂米的器具，用石头或木头制成，中间凹下。\n(2)形状像臼的～齿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臼"},{"id":"glyph-kai-8200","script":"kai","character":"舀","reading":"yǎo","description":"yǎo：用瓢、勺等取东西（多指流体）～水。～汤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舀"},{"id":"glyph-kai-8205","script":"kai","character":"舅","reading":"jiù","description":"jiù：(1)母亲的弟兄～～。～父。～母。\n(2)妻的弟兄妻～。\n(3)古代称丈夫的父亲～姑（公婆）。昔者吾～死于虎”。\n(4)古代帝王称异姓大邦诸侯为伯舅”，异姓蓄诸侯为叔舅”。诸侯亦称异姓大夫为舅”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舅"},{"id":"glyph-kai-8206","script":"kai","character":"舆","reading":"yú","description":"车辆,尤指马车\n轿子\n①车箱。\n②车。\n③指载柩车。\n④轿子。\n⑤制作车箱的工匠。\n⑥古代职位低贱的吏卒。\n⑦特指驾车的人。\n⑧抬;扛。\n⑨运载。\n舆2 yù通\"誉\"。名誉;荣誉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舆"},{"id":"glyph-kai-820c","script":"kai","character":"舌","reading":"shé","description":"shé：(1)人或动物嘴里辨别滋味、帮助咀嚼和发音的器官～头。～耕（ａ．指读书勤奋；ｂ．旧时学者授徒，依口说谋生，好像农夫耕田得粟）。唇枪～剑。\n(2)语言辩论的代称～战（激烈议论）。\n(3)像舌头的东西帽～。火～。\n(4)铃或释中的锤。\n(5)指箭靶两旁上下伸出的部分。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舌"},{"id":"glyph-kai-820d","script":"kai","character":"舍","reading":"shě；shè","description":"shè：(1)居住的房子宿～。旅～。校～。\n(2)居住，休息～于山麓。\n(3)谦辞，多指亲属中比自己年纪小或辈分低的～弟。～侄。～亲。\n(4)古代行军一宿或三十里为一舍退避三～（喻对人让步）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舍"},{"id":"glyph-kai-8212","script":"kai","character":"舒","reading":"shū","description":"shū：(1)展开，伸展～展。～畅。～张。～卷（juǎn）。～适。～心。\n(2)从容，缓慢～缓。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舒"},{"id":"glyph-kai-8214","script":"kai","character":"舔","reading":"tiǎn","description":"tiǎn：用舌头接触东西或取东西。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舔"},{"id":"glyph-kai-821e","script":"kai","character":"舞","reading":"wǔ","description":"wǔ：(1)按一定的节奏转动身体表演各种姿势～蹈。～技。～姿。～会。～剑。～女。～曲。～台。\n(2)耍弄～弊。～文弄墨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舞"},{"id":"glyph-kai-821f","script":"kai","character":"舟","reading":"zhōu","description":"zhōu：船～辑。龙～。轻～。一叶扁～。泛～。同～共济。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舟"},{"id":"glyph-kai-822a","script":"kai","character":"航","reading":"háng","description":"háng：(1)船。\n(2)行船或飞行～海。～空。～天。～行（xíng）。～班。民～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-航"},{"id":"glyph-kai-822c","script":"kai","character":"般","reading":"bān","description":"bān：(1)样，种，类这～。那～。百～。～配。暴风雨～的掌声。\n(2)古同班”，散布，分布。\n(3)同搬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-般"},{"id":"glyph-kai-8230","script":"kai","character":"舰","reading":"jiàn","description":"舰,御敌船\n十舰最著前。\n任何大型的航海的船只\n用桨、橹、帆或动力推进的有甲板或没有甲板的军用小船","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舰"},{"id":"glyph-kai-8231","script":"kai","character":"舱","reading":"cāng","description":"船或飞机中分隔开来载人或装东西的部分\n构成宇宙飞船整体结构的一部分的一个独立单元\n船上用来盛水、油或液体的分隔仓柜\n①船或飞机中隔开用来载人或装行李物品的部分船～、客～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舱"},{"id":"glyph-kai-8235","script":"kai","character":"舵","reading":"duò","description":"duò：船、飞机等控制方向的装置升降～。方向～。～轮（轮船、汽车等的方向盘）。～手。～位。～盘。掌～。见风使～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舵"},{"id":"glyph-kai-8236","script":"kai","character":"舶","reading":"bó","description":"bó：航海的大船船～（对船的通称）。巨～。～。～来品（指外国输入的货物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舶"},{"id":"glyph-kai-8239","script":"kai","character":"船","reading":"chuán","description":"chuán：水上交通工具～舶。～只。～舱。～帆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-船"},{"id":"glyph-kai-8247","script":"kai","character":"艇","reading":"tǐng","description":"tǐng：(1)轻便的小船游～。汽～。\n(2)某些大船潜水～。鱼雷～。舰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艇"},{"id":"glyph-kai-8258","script":"kai","character":"艘","reading":"sōu","description":"sōu：量词，指船只三～轮船。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艘"},{"id":"glyph-kai-826f","script":"kai","character":"良","reading":"liáng","description":"liáng：(1)好～好。善～。～辰美景。～知～能（中国古代唯心主义哲学家指人类不学而知的、不学而能的、先天具有的判断是非与善恶的能力）。～莠不齐。\n(2)很～久。～多趣味。用心～苦。\n(3)诚然，的确古人秉烛夜游，～有以也”。以为犬～我友”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-良"},{"id":"glyph-kai-8270","script":"kai","character":"艰","reading":"jiān","description":"艰难;困难\n⒉〈古〉指父丧或母丧丁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艰"},{"id":"glyph-kai-8272","script":"kai","character":"色","reading":"sè","description":"sè：(1)由物体发射、反射的光通过视觉而产生的印象颜～。～彩。～相（xiàng）。～调（diào）。\n(2)脸上表现出的神气、样子脸～。气～。～厉内荏。\n(3)情景，景象行～匆匆。景～宜人。\n(4)种类各～用品。\n(5)品质，质量音～。成～。足～纹银。\n(6)妇女美貌姿～。～艺。\n(7)情欲～情∶（hào）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-色"},{"id":"glyph-kai-8273","script":"kai","character":"艳","reading":"yàn","description":"文辞华丽\n⒈长得漂亮美而～。\n⒉色彩鲜明，文辞华美～丽。鲜～。百花争～。信言不～。\n⒊喜爱，羡慕～羡。\n⒋指爱情方面的事～史。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艳"},{"id":"glyph-kai-827a","script":"kai","character":"艺","reading":"yì","description":"技能;才能\n⒈才能，技能，本领手～。技～。～人。文～。～能。\n⒉同蓺。\n⒊度，准则贪欲无～。用人无～。\n②才能或方法领导～术。管理～术。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艺"},{"id":"glyph-kai-827e","script":"kai","character":"艾","reading":"ài","description":"ài：(1)多年生草本植物，嫩叶可食，老叶制成绒，供针灸用～子。～蒿。～绒。\n(2)止，绝方兴未～。\n(3)美好少（shào）～（年轻美好的女子）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艾"},{"id":"glyph-kai-8282","script":"kai","character":"节","reading":"jié","description":"节骨眼，节骨眼儿\n榞枅祵溃樬蕩畧?\n做工作要抓住节骨眼儿,别乱抓一气\n节子\n⒉见jié。\n⒈植物茎上分枝长叶的部位。特指竹节枝～。〈引〉人或动物的骨节肘关～。\n⒉时节，季节寒暑易～。〈引〉节日春～。八一建军～。十一国庆～。重阳～。\n⒊礼度礼～。\n⒋事项，事物的分段情～。章～。\n⒌音乐、舞蹈中有规律的强弱、长短、快慢等的表现～奏。～拍。\n⒍省减，限制，管辖～约。～制生育。这个兵团归他～制。〈引〉择要摘取～录几条。～译本。\n⒐〈古〉使臣出使外国时所持的凭证符～。旌～◇称出使外国的人为\"使节\"。\n⒑量词两～课。四～电池。五～火车。\n⒒一种用竹编的古乐器击～。\n⒓航行速度单位，符号kn，1节=1浬/时。\n⒔船舰划分锚链的长度单位，1节=2.5米锚链。\n⒖见jiē。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-节"},{"id":"glyph-kai-828b","script":"kai","character":"芋","reading":"yù","description":"yù：(1)多年生草本植物，作一年生栽植培。地下有肉质的球茎，含淀粉很多，可供食用，亦可药用。俗称芋奶”、芋艿”、芋头”。\n(2)指马铃薯”洋～。\n(3)指甘薯”山～。\n(4)指荸荠”乌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芋"},{"id":"glyph-kai-8292","script":"kai","character":"芒","reading":"máng","description":"máng：(1)某些禾本科植物种子壳上的细刺针尖对麦～。初露锋～。\n(2)像芒的东西光～。\n(3)多年生草本植物，叶细长有尖，叶除可作绿篱和布置庭园外，又可作造纸原料和编织草鞋，嫩叶可做牛的饲料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芒"},{"id":"glyph-kai-8299","script":"kai","character":"芙","reading":"fú","description":"fú：〔～蓉〕ａ．落叶灌木，花有红、黄、白各色，别于荷花，亦称木芙蓉”；ｂ．荷花的别称。\n〔～蕖〕荷花的别称。\n〔～蓉城〕中国四川省成都市的别称，简称蓉城”或蓉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芙"},{"id":"glyph-kai-829c","script":"kai","character":"芜","reading":"wú","description":"杂乱\n⒈荒废～城。田园荒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芜"},{"id":"glyph-kai-829d","script":"kai","character":"芝","reading":"zhī","description":"zhī：〔灵～〕见灵”。\n〔～兰〕芝”和兰”，古书上指两种香草，喻德行的高尚或友情、环境的美好等，如～～之室”、～～玉树”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芝"},{"id":"glyph-kai-82a5","script":"kai","character":"芥","reading":"jiè；gài","description":"jiè：小草，喻轻微纤细的事物草～。纤～。～舟。\n〔～菜〕一年或二年生草本植物，种子黄色，味辛辣，磨成粉末，称芥末”，作调味品。按用途分为叶用芥菜（如雪里蕻”）；茎用芥菜（如榨菜”）；根用芥菜（如大头菜”）。\ngài：〔～菜〕一年生草本植物，芥（jiè）菜的变种，叶大，表面多皱纹，叶脉显著，可食。亦作盖菜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芥"},{"id":"glyph-kai-82a6","script":"kai","character":"芦","reading":"lú","description":"lú：姓。\n〔～苇〕多年生草本植物，多生于水边，茎中空，茎可编席，亦可造纸。简称芦”，如～花”、～根”、～笛”、～席”、～荡”；亦简称苇”，如～丛”、～塘”、～箔”、～荡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芦"},{"id":"glyph-kai-82ac","script":"kai","character":"芬","reading":"fēn","description":"fēn：花草的香气～芳。清～。～香。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芬"},{"id":"glyph-kai-82ad","script":"kai","character":"芭","reading":"bā","description":"bā：古书上说的一种香草。\n〔～蕉〕ａ．多年生草本植物，叶宽大，叶柄一层一层紧裹着茎。叶和茎的纤维可编绳索；ｂ．这种植物的果实，跟香蕉相似。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芭"},{"id":"glyph-kai-82af","script":"kai","character":"芯","reading":"xīn；xìn","description":"xīn：去皮的灯心草灯～（亦作灯心”）。\nxìn：(1)物体的中心部分岩～。矿～。\n(2)装在器物中的捻子蜡～儿（蜡烛的捻子）。引～。\n(3)蛇和羊的舌头～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芯"},{"id":"glyph-kai-82b1","script":"kai","character":"花","reading":"huā","description":"huā：(1)植物的繁殖器官，典型的由花托”、花萼”、花冠”、雌蕊群”和雄蕊群”组成，有各种形状和颜色，一般长得很美丽，有的有香味，凋谢后结成果实。\n(2)供观赏的植物～木。～草。～匠。～事（游春看花等事）。\n(3)形状像花的东西雪～。浪～。钢～。火～。棉～（棉的絮亦称花）。礼～（烟火）。挂～（指战斗中受伤）。\n(4)用花装饰的～圈（quān）。～篮。～灯。～车。\n(5)具有条纹或图形的，不只一种颜色的～样。～边。～～绿绿。印～。\n(6)指痘”天～（一种急性传染病）。\n(7)混杂的，不单纯的～猫。～白头发。\n(8)虚伪的，用来迷惑人的～言巧语。\n(9)表面好看，没有实效的打～拳。～架子。\n(10)凝不清头昏眼～。\n(11)喻事业的精华体育之～。\n(12)喻女子姊妹～。\n(13)用掉～钱。\n(14)名目繁复的～名册（人员名册）。\n(15)犒赏的钱或物～红。\n(16)某些细嫩的东西蚕～。鱼～。\n(17)指妓女或与妓女有关的～娘（妓女）。～魁。\n(18)姓。\n〔～甲〕指六十岁，如年逾～～。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-花"},{"id":"glyph-kai-82b3","script":"kai","character":"芳","reading":"fāng","description":"fāng：(1)花草的香气～香。～草。～菲（ａ．花草的香气；ｂ．指花草）。～馥。～馨。芬～。\n(2)喻美好的～名。～龄（年龄，用于少女）。～姿（美好的姿态，用于少女）。～邻（关系融洽的邻居，用作敬辞）。流～百世。\n(3)花卉群～竞艳。～时（花盛时节）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芳"},{"id":"glyph-kai-82b9","script":"kai","character":"芹","reading":"qín","description":"qín：菜名，一年或二年生草本植物，茎可食。亦称水芹”。还有一种草芹”，有特殊香味，俗称药芹”。\n〔～献〕对人谦称所赠东西不好。亦称献芹”。\n〔～意〕谦辞，微薄的情意。\n〔～藻〕古代喻贡士或有才学之士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芹"},{"id":"glyph-kai-82bd","script":"kai","character":"芽","reading":"yá","description":"yá：(1)植物的幼体，可以发育成茎、叶或花的那一部分发～。嫩～。幼～。萌～。豆～。\n(2)形状像芽的东西肉～（伤口愈合后多长出的肉）。银～（银矿苗）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芽"},{"id":"glyph-kai-82c7","script":"kai","character":"苇","reading":"wěi","description":"芦苇，多年生草本植物，常生长在水边。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-82cd","script":"kai","character":"苍","reading":"cāng","description":"灰白色\n满面尘灰烟火色,两鬓苍苍十指黑。╠\n①青色～松。\n②灰白色，面色～白。\n③姓。\n【苍白】\n②形容缺乏旺盛的生命力～无力。\n①灰白色两鬓～。\n②苍茫天～，野茫茫。\n【苍黄】见【仓黄】。\n【苍凉】悲凉。\n【苍茫】空阔辽远；无边无际暮色～。\n【苍莽】苍茫。\n【苍穹】天空。又作穹苍。\n【苍生】古时指老百姓。\n【苍术】菊科，多年生草本植物。花白色或淡红色。其根茎含挥发油及较多量的维生素a、b，有健胃作用。分布于我国浙江、江苏、安徽等省。\n苍cǎng 1.见\"苍莽\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苍"},{"id":"glyph-kai-82cf","script":"kai","character":"苏","reading":"sū；sù","description":"sù：朝向～刃者死”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苏"},{"id":"glyph-kai-82d1","script":"kai","character":"苑","reading":"yuàn","description":"yuàn：(1)古代养禽兽植林木的地方，多指帝王的花园鹿～。御～。～囿。\n(2)学术、文艺荟萃之处文～。艺～。学～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苑"},{"id":"glyph-kai-82d4","script":"kai","character":"苔","reading":"tái；tāi","description":"tái：隐花植物的一类，根、茎、叶的区别不明显，常贴在阴湿的地方生长青～。～藓。～原。\ntāi：〔舌～〕舌头上面的垢腻，由衰死的上皮细胞和黏液等形成，观察它的颜色可以帮助论断病症。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苔"},{"id":"glyph-kai-82d7","script":"kai","character":"苗","reading":"miáo","description":"miáo：(1)初生的植物或没有秀穗的庄稼禾～。麦～。树～。幼～。～子（亦喻继承某种事业的接班人）。～而不秀（只长苗而不秀穗，喻本身条件虽好，但没有成就）。\n(2)形状像苗的火～儿。\n(3)某些初生的饲养的动物鱼～。\n(4)能使机体产生免疫力的微生物制剂疫～。卡介～。\n(5)子孙后代～裔。\n(6)中国少数民族，主要分布于贵州、湖南、云南、四川、湖北等省和广西壮族自治区～族。～绣。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苗"},{"id":"glyph-kai-82db","script":"kai","character":"苛","reading":"kē；hē","description":"kē：(1)过于严厉～刻。～毒。～求。～责。～待。\n(2)繁重，使人难以忍受～重（zhòng）。～捐杂税。\n(3)腐蚀性～性（如氢氧化钾、氢氧化钠等能腐蚀皮肤及纤维之类的化学性质）。～性钠（烧碱）。\nhē：古同诃”，谴责，责问。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苛"},{"id":"glyph-kai-82de","script":"kai","character":"苞","reading":"bāo","description":"bāo：(1)花托下面像叶的小片花～。～片‖～待放。\n(2)茂盛竹～松茂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苞"},{"id":"glyph-kai-82df","script":"kai","character":"苟","reading":"gǒu","description":"gǒu：(1)姑且，暂且～安。～延残喘。～且。\n(2)马虎，随便～得。～合。不敢～同。\n(3)如果，假使～非其人。～富贵，无相忘”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苟"},{"id":"glyph-kai-82e5","script":"kai","character":"若","reading":"ruò；rě","description":"ruò：(1)如果，假如～果。倘～。假～。天～有情天亦老。\n(2)如，像年相～。安之～素。旁～无人。置～罔闻。门庭～市。\n(3)你，汝～辈。更～役，复～赋，则何如？”\n(4)约计～干（gān）。～许。\n(5)此，如此以～所为，求～所欲，犹缘木而求鱼也。”\n(6)顺从曾孙是～。”\n(7)指海若”（古代神话中的海神）望洋向～而叹。”\n(8)指若木”（古代神话中的树名）。\n(9)指杜若”（古书上说的一种香草）沐兰泽，含～芳”。～英（杜若”的花）。\n(10)文言句首助词，常与夫”合用～夫阴雨霏霏，连月不开。”\n(11)用在形容词或副词后，表示事物的状态桑之未落，其叶沃～”。\nrě：〔般（bō）若〕见般3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-若"},{"id":"glyph-kai-82e6","script":"kai","character":"苦","reading":"kǔ","description":"kǔ：(1)像胆汁或黄连的滋味，与甘”相对甘～。～胆。～瓜。\n(2)感觉难受的～境。～海（原为佛教用语，后喻很苦的环境）。～闷‖辛茹～。吃～耐劳。～恼。\n(3)为某种事所苦～雨。～旱。～夏。～于（ａ．对某种情况感到苦脑；ｂ．表示相比之下更苦些）。\n(4)有耐心地，尽力地～劝。～口婆心。刻～。～心孤诣。\n(5)使受苦那件事可～了你啦！","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苦"},{"id":"glyph-kai-82f1","script":"kai","character":"英","reading":"yīng","description":"yīng：(1)花落～缤纷。\n(2)才能出众，才能出众的人～俊。群～荟萃。～才。～雄。～烈。\n(3)精华，事物最精粹的部分精～。～华‖～咀华。\n(4)用羽毛做的矛饰二矛重（chóng）～。\n(5)古同瑛”，似玉的美石。\n(6)指英国”～文。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-英"},{"id":"glyph-kai-82f9","script":"kai","character":"苹","reading":"píng；pēng","description":"pēng：〔～萦〕回旋的样子，如争湍～～，汨活澎濞”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苹"},{"id":"glyph-kai-8301","script":"kai","character":"茁","reading":"zhuó","description":"zhuó：(1)植物才生长出来的样子。\n(2)壮盛，壮健～壮。～实（实”读轻声）。～长（zhǎng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茁"},{"id":"glyph-kai-8302","script":"kai","character":"茂","reading":"mào","description":"mào：(1)草木旺盛～盛。丰～。\n(2)美，有才德～士。～才（即秀才”）。\n(3)有机化合物，环戊间二烯的简称。无色液体，用来制农药、塑料等。\n(4)古同懋”，勉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茂"},{"id":"glyph-kai-8303","script":"kai","character":"范","reading":"fàn","description":"假借为筪。法则\n典范\n模子\n⒈铸造器物的模子铜～。钱～。\n⒉楷模，榜样模～。典～。师～。示～表演。\n⒊一定的界限，限制～围。防～。就～。\n【范畴】\n①类型，范围此鱼属于鲫鱼～畴。\n②高度概括的基本概念。如化合、分解是化学的～畴；商品、价值是政治经济学的～畴；矛盾、质和量等是哲学的～畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-范"},{"id":"glyph-kai-8304","script":"kai","character":"茄","reading":"qié；jia","description":"qié：〔～子〕一年生草本植物，花紫色。果实一般为紫色，也有白色或绿色的，可食，如拌～泥”。\n〔番～〕一年生草本植物，花黄色。果实圆形，熟时红、黄色。亦称西红柿”，可食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茄"},{"id":"glyph-kai-8305","script":"kai","character":"茅","reading":"máo","description":"máo：多年生草本植物，春季先开花，后生叶，花穗上密生白毛。根茎可食，亦可入药。叶可编蓑衣（亦称白茅”）～草。～庐。～舍。名列前～（喻名次列在前面）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茅"},{"id":"glyph-kai-8309","script":"kai","character":"茉","reading":"mò","description":"mò：〔～莉〕ａ．常绿灌木，叶卵形，花白色，很香，常用来熏制茶叶；ｂ．一年生或多年生草本植物，花有红、白、黄、紫各色，果实圆形，成熟时黑色。根和种子可入药。花供观赏，可制化妆品。亦称草茉莉”、紫茉莉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茉"},{"id":"glyph-kai-830e","script":"kai","character":"茎","reading":"jīng","description":"柱;竿\n小枝\n器物的柄\n指长\n⒈植物的营养器官之一。它常是植物的主干，起支撑作用，又具有输送水分、养料和储存养料等作用。有些植物有地下茎，如藕、马铃薯、荸荠等，还可发生变态及进行无性繁\n殖。\n⒉量词，义同\"根\"几～麦秆。数～毛发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茎"},{"id":"glyph-kai-8327","script":"kai","character":"茧","reading":"jiǎn","description":"许多昆虫幼虫在化蛹前包围身体大部分的由丝组成的外皮,在其中化蛹。家蚕的茧是商业蚕丝的来源\n指茧丝\n絮丝棉的衣服\n通趼”。手掌或脚掌等部因摩擦而生成的硬皮\n形状如茧的\n⒈某些昆虫的幼虫在变成蛹之前吐丝或分泌某种物质做成的壳。家蚕、柞蚕和蓖麻蚕等的茧是缫丝的原料蚕～。家蚕～子。卖蚕～儿。\n⒉手、脚上因劳动、走路等摩擦而生的硬皮脚底有老～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茧"},{"id":"glyph-kai-832b","script":"kai","character":"茫","reading":"máng","description":"máng：(1)凝不清，对事理全无所知～然。～昧。\n(2)遥远，面积大，看不清边沿～～。～漠。渺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茫"},{"id":"glyph-kai-832c","script":"kai","character":"茬","reading":"chá","description":"chá：(1)庄稼收割后余留在地里的短茎和根～子。麦～。\n(2)同一块田地上庄稼种植或收割的次数头～。\n(3)短而硬的头发、胡子胡～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茬"},{"id":"glyph-kai-8335","script":"kai","character":"茵","reading":"yīn","description":"yīn：铺垫的东西，垫子、褥子、毯子的通称～褥。～席。～饪（寝褥和烹饪，引申为睡眠和饮食）。绿草如～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茵"},{"id":"glyph-kai-8336","script":"kai","character":"茶","reading":"chá","description":"chá：(1)常绿灌木，叶长椭圆形，有锯齿，经加工制为饮料，就是茶叶；秋末开花，白色；种子可榨油；木质致密，供雕刻用～树。～农。\n(2)特指茶叶”绿～§～。花～。沱～。龙井～。乌龙～。\n(3)用茶叶沏成的饮料～水。～饭。～点（茶水、点心）。～话会。～博士（善于烹茶的人，亦指卖茶的人或茶馆侍者）。～余饭后。\n(4)泛指某些饮料～汤。面～。果～。\n(5)特指茶点”早～。晚～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茶"},{"id":"glyph-kai-8338","script":"kai","character":"茸","reading":"róng","description":"róng：(1)草初生纤细柔软的样子绿～～的草地。\n(2)细柔的毛、发半脱紫～裘”。～毛。\n(3)指鹿茸”（带细毛的才生出来的鹿角，可入药）～客（指鹿）。参（shēn）～（指人参和鹿茸）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茸"},{"id":"glyph-kai-8346","script":"kai","character":"荆","reading":"jīng","description":"jīng：(1)落叶灌木，叶有长柄，掌状分裂，开蓝紫色小花，枝条可编筐篮等（亦称楚”）紫～。～条。～棘。披～斩棘。\n(2)古代用荆条做的刑仗负～请罪。\n(3)中国古代九州”之一，春秋时楚国别称～州。～璞（喻美质、未经任用的卓越人才）。\n(4)旧时对人谦称自己的妻子拙～。山～。～妻。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荆"},{"id":"glyph-kai-8349","script":"kai","character":"草","reading":"cǎo","description":"cǎo：(1)对高等植物中除了树木、庄稼、蔬菜以外的茎干柔软的植物的统称；广义指茎干比较柔软的植物，包括庄稼和蔬菜青～。野～。茅～。水～。花～。～鞋。～堂（茅草盖的堂屋，旧时文人以此自称山野间的住所，有自谦卑陋的意思）。～原。～坪。～行露宿。～菅人命。\n(2)特指用作燃料、饲料的稻麦之类的茎叶～料。柴～。稻～。\n(3)粗糙，不细致～率（shuài）。～鄙（粗野朴陋）。～具（粗劣的食物）。\n(4)汉字的一种书体～书。～字（亦为旧时谦称自己的别名）。章～（草书的一种，笔画保存了一些隶书的笔势，因其最初用于奏章，故名章草”）。狂～。～体（ａ．指汉字草书；ｂ．拼音文字的手写体，有大草、小草之分）。\n(5)打稿子，亦指稿子；引申为初步的，非正式的～拟。～诏（为皇帝草拟诏书）。\n(6)荒野，原野，引申为在野的、民间的～野。～莽。～寇。～贼。\n(7)雌性的（用于某些家畜、家禽）～鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-草"},{"id":"glyph-kai-8350","script":"kai","character":"荐","reading":"jiàn","description":"再;又;接连\n⒈介绍，推举推～能人。举～贤人。\n⒉动物能吃的草鹿食～。\n⒊草席，草垫。〈引〉垫～鞋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荐"},{"id":"glyph-kai-8352","script":"kai","character":"荒","reading":"huāng","description":"huāng：(1)年成不好，收成不好～年。灾～。防～。备～。\n(2)长满野草，或无人耕种～芜。～地。开～。\n(3)废弃～废。～疏。～置。业精于勤，～于嬉。\n(4)冷落偏僻～村。～郊。～落（luò）（ａ．荒凉冷落；ｂ．荒疏衰退）。～颓。\n(5)严重缺乏，不够用煤～。\n(6)不实在的，不正确的～信。～唐（ａ．浮夸，不实在；ｂ．行为放荡。唐”均读轻声）。\n(7)放纵，迷乱～淫。～腆（沉湎于酒）。\n(8)远，边远的地方～远。～遐。八～。\n(9)扩大天作高山大王～之”。\n(10)包有奄有龟蒙，遂～大东，至于海邦”。\n(11)工业上指没有经过精细加工的～子（毛坯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荒"},{"id":"glyph-kai-8354","script":"kai","character":"荔","reading":"lì","description":"lì：〔～枝〕ａ．常绿乔木，果实球形，果实外壳有瘤状突起，熟时紫红色，果肉白色半透明，多汁，味甜美；ｂ．这种植物的果实。均亦称离枝”、丹荔”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荔"},{"id":"glyph-kai-8361","script":"kai","character":"荡","reading":"dàng","description":"动;摇动;震动\n清除\n①摇动；摆动动～、飘～。\n②无事走来走去；闲～。\n③清洗～涤。\n④清除全部弄光；扫～。\n⑤放纵；行为不检点放～。\n⑥浅水湖芦苇～。\n【荡涤】冲洗；清除。\n【荡气回肠】见【回肠荡气】。\n【荡然】形容原有的东西完全消失～无存。\n荡tàng 1.量词。\n荡tāng 1.古水名。即今之汤水，在河南省汤阴县北境。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荡"},{"id":"glyph-kai-8363","script":"kai","character":"荣","reading":"róng","description":"草本植物的花。又为花的通称\n飞檐,屋檐两头翘起的部分\n⒈草开花，草的花或谷类结穗草～。无叶无～。黍～。\n⒉茂盛，兴盛欣欣向～。繁～富强。\n⒊光荣，受人 敬重～誉。～耀。～军。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荣"},{"id":"glyph-kai-8364","script":"kai","character":"荤","reading":"hūn","description":"指鸡、鸭、鱼、肉等食物。与素”相对\n⒈肉食～菜。吃～。\n⒉有特殊气味的蔬菜，如葱、蒜等～辛。五～。\n⒊粗俗，下流全是～话。\n荤xūn 1.见\"荤粥\"﹑\"荤允\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荤"},{"id":"glyph-kai-8367","script":"kai","character":"荧","reading":"yíng","description":"萤火\n眩惑\n⒈微弱的光亮。\n⒉使人目眩。\n①火星。\n②迷惑～惑人心。\n荧xíng 1.水名。故址在今河南省郑州市西北。\n荧jiǒng 1.药草名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荧"},{"id":"glyph-kai-836b","script":"kai","character":"荫","reading":"yīn","description":"日影\n指地窖或暗室\n⒈阳光被遮，又凉又潮树～。那间房很～。\n⒉遮盖榆柳～后簷。\n⒊保佑，庇护庇～。\n⒋封建时代帝王给予有官爵大臣的子孙读书或做官等之特权封赏。\n荫yīn 1.树荫。 2.日影。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荫"},{"id":"glyph-kai-836f","script":"kai","character":"药","reading":"yào","description":"⒈治病的物品中～。开～方。～物治疗。\n⒉有某些作用的化学物品火～。炸～。农～。消毒～。\n⒊治疗无可救～。\n药shuò 1.热貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-药"},{"id":"glyph-kai-8377","script":"kai","character":"荷","reading":"hé","description":"hé：即莲”。\n〔～包〕ａ．佩戴的小囊；ｂ．食品名。\n〔～尔蒙〕激素”的旧称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荷"},{"id":"glyph-kai-8389","script":"kai","character":"莉","reading":"lì","description":"lì：〔茉～〕见茉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莉"},{"id":"glyph-kai-83ab","script":"kai","character":"莫","reading":"mò；mù","description":"mò：(1)不要～哭。\n(2)没有，无～大。～非。～名其妙（亦作莫明其妙”）。\n(3)不，不能～如。～逆。～须有。～衷一是（不能得出一致的结论）。爱～能助。\n(4)古同漠”，广大。\n(5)姓。\nmù：古同暮”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莫"},{"id":"glyph-kai-83b1","script":"kai","character":"莱","reading":"lái","description":"草名,又名藜\n郊外休耕的田\n古国名\n长满杂草\n⒈藜。\n⒉［莱菔］萝卜～菔子可供药用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莱"},{"id":"glyph-kai-83b2","script":"kai","character":"莲","reading":"lián","description":"也称芙蓉、芙蕖、菡萏等。多年生草本植物,生浅水中。叶子大而圆,叫荷叶。花有粉红、白色两种。种子叫莲子,包在倒圆锥形的花托内,合称莲蓬。地下茎叫藕\n莲lián即\"荷\"。\n莲liǎn 1.地名用字『有莲勺县。故址在今陕西省渭南县东北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莲"},{"id":"glyph-kai-83b7","script":"kai","character":"获","reading":"huò","description":"俘获\n⒈猎得，捉住捕～。俘～。缴～。\n⒉得到，取得～胜归来。不劳而～。～得巨大成绩。\n⒊收割庄稼收～归来。秋～冬藏。也指所取得的成果努力学习，必有收～。\n获hù 1.争取，争得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-获"},{"id":"glyph-kai-83b9","script":"kai","character":"莹","reading":"yíng","description":"似玉的宝石\n光洁透明\n使明洁。使生光泽\n夫良玉未剖,与百石相类;名\n⒈像玉的石头如玉如～。\n⒉光洁，明亮，玉石的光彩晶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莹"},{"id":"glyph-kai-83ba","script":"kai","character":"莺","reading":"yīng","description":"黄莺\n⒈鸟名。种类很多。常见的有树～、柳～、鹪～等。身体多比麻雀小，羽毛绿褐色或灰褐色，嘴尖短，鸣声清脆。主食昆虫，是益鸟，要保护，禁止猎杀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莺"},{"id":"glyph-kai-83bd","script":"kai","character":"莽","reading":"mǎng","description":"mǎng：(1)草，密生的草～原。草～。\n(2)广大，辽阔～苍。～～（ａ．形容原野辽阔，无边无际；ｂ．形容草木茂盛）。\n(3)古书上指一种短节竹。\n(4)粗鲁，冒失～汉。～撞。鲁～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莽"},{"id":"glyph-kai-83c7","script":"kai","character":"菇","reading":"gū","description":"gū：蕈，菌类植物香～。冬～。蘑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菇"},{"id":"glyph-kai-83ca","script":"kai","character":"菊","reading":"jú；jv","description":"jú：(1)多年生草本植物，秋天开花，是观赏植物，有的花可以入药，亦可作饮料～花。赏～。春兰秋～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菊"},{"id":"glyph-kai-83cc","script":"kai","character":"菌","reading":"jūn；jùn","description":"jūn：低等植物的一大类，不开花，没有茎和叶子，不含叶绿素，不能自己制造养料，过寄生生活，种类繁多细～。真～。病～。～肥。\njùn：即蕈”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菌"},{"id":"glyph-kai-83dc","script":"kai","character":"菜","reading":"cài","description":"cài：(1)供作副食品的植物～市。白～。菠～。野～。蔬～。面有～色。\n(2)主食以外的食品～牛。～畜。～肴。～谱。名～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菜"},{"id":"glyph-kai-83e0","script":"kai","character":"菠","reading":"bō","description":"bō：〔～菜〕一年生或二年生草本植物，叶子略呈三角形，根红色，含甜味，根和茎、叶均可食。\n〔～萝〕ａ．多年生草本植物。果实密集在一起，外部呈麟片状，果肉甜酸，产于热带；ｂ．这种植物的果实，亦称凤梨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菠"},{"id":"glyph-kai-83e9","script":"kai","character":"菩","reading":"pú","description":"pú：〔～提〕ａ．佛教指豁然开朗的彻悟境界，又指觉悟的智慧和途径；ｂ．常绿乔木，树上的汁液可制硬性橡胶。原产于印度。\n〔～萨〕ａ．佛教指释迦牟尼修行尚未成佛时的称号，后指修行到一定程度，地位仅次于佛的人；ｂ．泛指佛和某些神；ｃ．喻慈善的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菩"},{"id":"glyph-kai-83f1","script":"kai","character":"菱","reading":"líng","description":"líng：一年生水生草本植物，果实有硬壳，有角，称菱”或菱角”，可食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菱"},{"id":"glyph-kai-83f2","script":"kai","character":"菲","reading":"fēi；fěi","description":"fēi：(1)花草茂盛，香气浓郁～～，芳～。\n(2)碳氢化合物的一类，无色有光泽的结晶，可制染料、炸药等。\nfěi：(1)微，薄～才。～仪。～酌。～薄。\n(2)古代指芜菁一类的植物，花紫红色，可作菜用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菲"},{"id":"glyph-kai-8404","script":"kai","character":"萄","reading":"táo","description":"táo：〔葡～〕见葡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萄"},{"id":"glyph-kai-840c","script":"kai","character":"萌","reading":"méng","description":"méng：(1)植物的芽～蘖。\n(2)发芽，开始发生～生。～发。～芽。～动。故态复～。\n(3)古同氓1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萌"},{"id":"glyph-kai-840d","script":"kai","character":"萍","reading":"píng","description":"píng：一年生草本植物，浮生水面，叶子扁平，表面绿色，背面紫红色，叶下生须根，开白花，称浮萍”，亦称青萍”、紫萍”，多用以喻不定的生活或行踪～泊。～踪。～水相逢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萍"},{"id":"glyph-kai-840e","script":"kai","character":"萎","reading":"wěi","description":"wěi：干枯衰落～谢。～蔫。～顿（亦作委顿”）。～靡。～缩。枯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萎"},{"id":"glyph-kai-841d","script":"kai","character":"萝","reading":"luó","description":"⒈通常指某些能爬蔓的植物茑～。藤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萝"},{"id":"glyph-kai-8424","script":"kai","character":"萤","reading":"yíng","description":"动物名。节肢动物门,昆虫纲。萤火虫\n比喻微弱的亮光","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萤"},{"id":"glyph-kai-8425","script":"kai","character":"营","reading":"yíng","description":"围绕;缠绕\n扎营\n⒈经管，料理经～。国～。私～。～业。～护。\n⒉谋求～利。～救。～私舞弊。无～无欲。\n⒊建造～造。～城市。\n⒋军队驻扎的地方或集体到野外活动的住地军～。夏令～。\n⒌军队编制单位团的下一级，连的上一级。\n①生物从外界摄取需要的养料，以维持生活的作用。\n②养分，养料禽蛋、豆类富于～养。\n营cuō 1.见\"烛营\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-营"},{"id":"glyph-kai-8427","script":"kai","character":"萧","reading":"xiāo","description":"古国名\n县名\n萧条,冷落;荒凉\n⒈〈古〉称香蒿，也叫\"青蒿\"。\n⒉冷落，冷静～然。～索。\n①冷落寂寞景象～条。\n②停滞，萎缩经济～条。\n①树木被秋风吹动的声音秋风～瑟。\n②冷落凄凉的样子。\n⒎\"萧\"姓，俗写作\"肖\"。\n萧xiāo 1.蒿类植物的一种。即艾蒿。 2.萧条冷落;凄凉。 3.稀疏。 4.指萧斧。 5.见\"萧森\"。 6.见\"萧然\"。 7.通\"肃\"。参见\"萧墙\"﹑\"萧斧\"。 8.古国名。春秋\n时宋的附庸，子姓。在今安徽省萧县西北。公元前597年灭于楚◇仍为宋邑。 9.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萧"},{"id":"glyph-kai-8428","script":"kai","character":"萨","reading":"sà","description":"佛教用语,即菩萨\n姓。明有萨琦","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萨"},{"id":"glyph-kai-843d","script":"kai","character":"落","reading":"luò；là；lào","description":"luò：掉下，下降；停留、归属。là：遗漏，丢下。lào：用于落枕、落色等词。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-8457","script":"kai","character":"著","reading":"zhù","description":"zhù：(1)显明，显出～名。～称。显～。昭～。卓～。\n(2)写文章，写书～述。编～。～书立说。\n(3)写作出来的书或文章名～。巨～。遗～。译～。～作。\n(4)古同贮”，居积。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-著"},{"id":"glyph-kai-845b","script":"kai","character":"葛","reading":"gě；gé","description":"gé：(1)多年生草本植物，茎可编篮做绳，纤维可织布，块根肥大，称葛根”，可制淀粉，亦可入药（通称葛麻”）～布。～巾（葛布做的头巾，古人不分贵贱常服）。～履。\n(2)表面有花纹的纺织品，用丝做经，棉线或麻线等做纬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葛"},{"id":"glyph-kai-8461","script":"kai","character":"葡","reading":"pú","description":"pú：〔～萄〕ａ．落叶藤本植物，果实圆形或椭圆形，味甜可食，亦可酿酒；ｂ．这种植物的果实或像其形者，如～～干”。～～酒”。～～球菌”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葡"},{"id":"glyph-kai-8463","script":"kai","character":"董","reading":"dǒng","description":"dǒng：(1)监督管理～统。～督。～正（督察纠正）。～理。～事（某些企业、学校的资产所有者推举出来代表自己监督和主持业务的人）。～其成。\n(2)正余将～道而不豫兮”。\n(3)深藏年六十已上，气当大～”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-董"},{"id":"glyph-kai-846b","script":"kai","character":"葫","reading":"hú","description":"hú：大蒜的别称。\n〔～芦〕ａ．一年生草本植物，果实像大小两个球连在一起，可以盛酒或供观赏；ｂ．这种植物的果实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葫"},{"id":"glyph-kai-846c","script":"kai","character":"葬","reading":"zàng","description":"zàng：掩埋死人，泛指处理死者遗体安～。埋～。土～。火～。～。～送。～礼。～仪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葬"},{"id":"glyph-kai-8471","script":"kai","character":"葱","reading":"cōng","description":"cōng：(1)多年生草本植物，叶圆筒状，中空，茎叶有辣味，是常用的蔬菜或调味品，兼作药用，品种很多大～。小～。\n(2)青色～翠。～白。～绿。～茏（形容草木青翠茂盛）。～郁。郁郁～～。\n〔～头〕ａ．多年生草本植物，地下有扁球形鳞，白色或略带紫红色，可食；ｂ．这种植物的鳞茎。亦称洋葱”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葱"},{"id":"glyph-kai-8475","script":"kai","character":"葵","reading":"kuí","description":"kuí：〔向日～〕一年生草本植物，茎很高，开大黄花，花常朝向太阳，子可食，亦可榨油。简称葵”，如～花”，～心”。\n〔锦～〕一年生或多年生草本植物，夏季开淡紫色或白色花，供观赏。\n〔蜀～〕多年生草本植物，花有红、紫、白等色，根可入药。亦称胡葵”、吴葵”、一丈红”。\n〔冬～〕一年生草本植物，果实扁圆形。种子、根、茎、叶均可入药。简称葵”。\n〔蒲～〕常绿乔木，叶大，大部分掌状分裂，裂片长披针形，木材可制器具，叶可做蓑、笠及扇。简称葵”，如～扇”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葵"},{"id":"glyph-kai-8482","script":"kai","character":"蒂","reading":"dì","description":"dì：花或瓜果跟枝茎相连的部分花～。瓜～。～芥。根深～固。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒂"},{"id":"glyph-kai-848b","script":"kai","character":"蒋","reading":"jiǎng","description":"古国名\n蒋jiāng 1.植物名。菰。即茭白。 2.见\"蒋蒋\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒋"},{"id":"glyph-kai-8499","script":"kai","character":"蒙","reading":"méng；měng","description":"měng：〔～古族〕a.中国少数民族之一。b.蒙古国的主要民族。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒙"},{"id":"glyph-kai-849c","script":"kai","character":"蒜","reading":"suàn","description":"suàn：多年生草本植物，地下鳞茎分瓣，按皮色不同分为紫皮种和白皮种。味辣，有刺激性气味，可食用或供调味，亦可入药（通称大蒜”）～头。～苗。～黄。～毫。～薹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒜"},{"id":"glyph-kai-84b2","script":"kai","character":"蒲","reading":"pú","description":"pú：(1)多年生草本植物，生池沼中，高近两米。根茎长在泥里，可食。叶长而尖，可编席、制扇，夏天开黄色花（亦称香蒲”）～黄（蒲的花粉）。～棒。～草。～绒。～扇。\n(2)指菖蒲”～节。～月（指农历五月）。\n(3)庵，用草盖的圆形屋。\n(4)古同匍”，匍伏。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒲"},{"id":"glyph-kai-84b8","script":"kai","character":"蒸","reading":"zhēng","description":"zhēng：(1)热气上升～汽。～腾。～发。～气（液体或固体因蒸发沸腾或升华而变成的气体）。～馏。云～霞蔚。～～日上。\n(2)用水蒸气的热力把东西加热或使熟～饼。～饺。～笼。\n(3)古代以麻秸、竹木制成的火炬～烛。\n(4)细小的木柴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒸"},{"id":"glyph-kai-84c4","script":"kai","character":"蓄","reading":"xù","description":"xù：(1)积聚，储藏，保存～藏。～洪。～发（fà）。～养。积～。储～。兼收并～。\n(2)存于心中～志。～怨。～谋。～意‖～。\n(3)等待孰谓时之可～？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓄"},{"id":"glyph-kai-84c9","script":"kai","character":"蓉","reading":"róng","description":"róng：(1)用某些植物的果肉或种子制成的粉状物椰～。豆～。\n(2)中国四川省成都市的别称～城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓉"},{"id":"glyph-kai-84dd","script":"kai","character":"蓝","reading":"lán","description":"佛寺。梵语伽蓝的简称\n颜色的一种。像晴天天空的颜色\n⒈蓝色，像晴空那样的颜色～天。天～色。\n⒉蓼蓝，一年生草本。叶子提制的靛青，可做染料，染出的颜色就是青青出于～，而胜于～。\n⒊［蓝本］著作所依据的原本。\n⒋［蓝图］一种复制图。〈喻〉建设的计划。\n蓝lan 1.苤蓝。甘蓝的一种。是普通蔬菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓝"},{"id":"glyph-kai-84ec","script":"kai","character":"蓬","reading":"péng","description":"péng：(1)多年生草本植物，花白色，中心黄色，叶似柳叶，子实有毛（亦称飞蓬”）～门。～心（蓬”的心狭窄而弯曲，喻茅塞不通的头脑。谦辞，用以表示自己见识浅陋，蠢笨）。～户瓮牗。～生麻中（喻在良好的生长环境里，自然会受到好的影响）。～荜生辉（使得自家有了光彩。谦辞，用来称谢别人字画等物品的赠予或客人的来访）。\n(2)散乱～乱。～松。～头垢面。\n(3)茂盛，旺盛～勃。\n(4)量词，用于类似成丛飞蓬的东西一～凤尾竹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓬"},{"id":"glyph-kai-8511","script":"kai","character":"蔑","reading":"miè","description":"细小;轻微\n轻视;轻侮。亦作懱”\n⒈微小～视。\n⒉无～不济矣。\n⒊污血。〈引〉以血涂人，即诋毁别人污～。诬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔑"},{"id":"glyph-kai-8513","script":"kai","character":"蔓","reading":"màn；wàn","description":"wàn：细长能缠绕的茎瓜～儿。\n〔大～儿（wànr）〕方言，指有较高表演技艺，有广泛影响的演艺明星。亦作大腕儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔓"},{"id":"glyph-kai-8517","script":"kai","character":"蔗","reading":"zhè","description":"zhè：〔甘～〕多年生草本植物，茎直立，有节，含甜汁很多，可生吃，亦可制糖。副产品糖蜜可酿酒、制酒精。简称蔗”，如～农”。～糖”。～渣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔗"},{"id":"glyph-kai-851a","script":"kai","character":"蔚","reading":"wèi","description":"wèi：(1)茂盛，荟聚，盛大～然成风。～为大观。～蓝（晴朗天空的颜色）。\n(2)文采华丽云蒸霞～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔚"},{"id":"glyph-kai-8521","script":"kai","character":"蔡","reading":"cài","description":"cài：(1)野草。\n(2)中国周代诸侯国名，在今河南省上蔡县、新蔡县一带。\n(3)占卜用的大龟蓍～。\n(4)杀，减三百里夷，二百里～”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔡"},{"id":"glyph-kai-852c","script":"kai","character":"蔬","reading":"shū","description":"shū：可做菜吃的植物（多属草本）～菜。菜～。布衣～食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔬"},{"id":"glyph-kai-853c","script":"kai","character":"蔼","reading":"ǎi","description":"树木生长繁茂\n盛多的样子\n和气,态度好\n云气。通霭”\n蔼 ǎi和气，和善对人和～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔼"},{"id":"glyph-kai-853d","script":"kai","character":"蔽","reading":"bì","description":"bì：(1)遮，挡～野。遮～。掩～。\n(2)隐藏～匿。隐～。\n(3)欺骗，隐瞒蒙～。～美扬恶。\n(4)概括一言以～之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔽"},{"id":"glyph-kai-8549","script":"kai","character":"蕉","reading":"jiāo","description":"jiāo：(1)指某些有像芭蕉那样的大叶子的植物香～。美人～。\n(2)生麻，未沤治的麻。\n(3)古同焦”，枯焦。\n〔芭～〕见芭”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕉"},{"id":"glyph-kai-854a","script":"kai","character":"蕊","reading":"ruǐ","description":"ruǐ：(1)植物生殖器官的一部分花～。雄～。雌～。\n(2)草木丛生。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕊"},{"id":"glyph-kai-8574","script":"kai","character":"蕴","reading":"yùn","description":"字亦作蕴”。\n包藏;包含\n乱麻\n⒈积聚，蓄藏～藏。～蓄。\n⒉深奥精～。\n⒊郁结～愤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕴"},{"id":"glyph-kai-857e","script":"kai","character":"蕾","reading":"lěi","description":"lěi：含苞未放的花，花骨朵花～。蓓～。～铃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕾"},{"id":"glyph-kai-8584","script":"kai","character":"薄","reading":"báo；bó；bò","description":"báo：厚度小，如薄纸。bó：微少，不厚道；轻视，如薄礼、刻薄、厚古薄今。bò：用于薄荷。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-8587","script":"kai","character":"薇","reading":"wēi","description":"wēi：一年生或二年生草本植物，结荚果，中有种子五六粒，可食。嫩茎和叶可做蔬菜。通称巢菜”、大巢菜”、野豌豆”。\n〔紫～〕a.落叶小乔木。开紫红色或白色花，结球形蒴果。供观赏；b.这种植物的花。均通称满堂红”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薇"},{"id":"glyph-kai-859b","script":"kai","character":"薛","reading":"xuē","description":"xuē：(1)中国周代诸侯国名，在今山东省滕县南。\n(2)古书上指一种蒿类植物。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薛"},{"id":"glyph-kai-85aa","script":"kai","character":"薪","reading":"xīn","description":"xīn：柴火～苏（打柴割草）。～尽火传（chuán）（柴火烧完，又引燃了后一根柴，火永远不灭。原指人形骸有尽而精神未死，后亦用以喻思想学问、技艺代代相传）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薪"},{"id":"glyph-kai-85af","script":"kai","character":"薯","reading":"shǔ","description":"shǔ：〔～莨〕a.多年生草本植物，地上有缠绕茎，地下块茎，可用来染棉、麻织品；b.这种植物的果实。\n〔～蓣〕多年生草本植物，茎蔓生，块根为圆柱形，可食。通称山药”。\n〔甘～〕a.一年生或多年生草本植物，蔓匍匐地面。块根可食，亦可制糖和酒精；b.这种植物的块根。均通称红薯”、白薯”；亦称番薯”、山芋”、地瓜”、红苕”。\n〔马铃～〕a.多年生草本植物，地下块茎可食；ｂ．这种植物的块茎。均亦称土豆儿”、山药蛋”、洋芋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薯"},{"id":"glyph-kai-85c9","script":"kai","character":"藉","reading":"jiè；jí","description":"jiè：(1)垫在下面的东西。\n(2)衬垫枕～。\n(3)同借”③④。\n(4)抚慰慰～。\n(5)含蓄蕴～。\n(6)假设，假使公等遇雨，皆已失期，失期当斩。～第令毋斩，而戍死者固十六七”。\njí：(1)践踏，凌辱人皆～吾弟”。狼～。\n(2)进贡其～于成周”。\n(3)姓。\n〔～～〕同籍籍”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藉"},{"id":"glyph-kai-85cf","script":"kai","character":"藏","reading":"cáng；zàng","description":"cáng：隐藏、收藏。zàng：储藏东西的地方；佛教等经典的总汇；用于西藏、藏族等名称。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-85d0","script":"kai","character":"藐","reading":"miǎo","description":"miǎo：(1)小，幼～孤。～小。\n(2)轻视～视。言者谆谆，听者～～。\n(3)古同邈”，远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藐"},{"id":"glyph-kai-85d5","script":"kai","character":"藕","reading":"ǒu","description":"ǒu：莲的地下茎，肥大有节，中间有管状小孔，折断后有丝，可食～粉。～断丝连。～色。～荷（淡紫色）。～节。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藕"},{"id":"glyph-kai-85e4","script":"kai","character":"藤","reading":"téng","description":"téng：(1)指白藤”、紫藤”～条。～椅。～床。\n(2)泛指匍匐茎或攀援茎～本植物。瓜～。葡萄～。顺～摸瓜。\n〔～黄〕a.常绿乔木，茎高达二十米，树脂黄色，有毒；b.这种植物的树脂，可作国画颜料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藤"},{"id":"glyph-kai-85fb","script":"kai","character":"藻","reading":"zǎo","description":"zǎo：(1)隐花植物的一大类，无根、茎、叶等部分的区别，有叶绿素可以自己制造养料，种类很多，海水和淡水里都有，极少数可生活在陆地的阴湿地方水～。～。小球～。～类植物。\n(2)泛指生长在水中的植物，亦包括某些水生的高等植物狸～。金鱼～。\n(3)指华丽的文彩、文辞～思（多采的文思）。～丽。～绘（文采）。～井（中国传统建筑物天花板上一方一方的彩画）。～镜（指品评鉴别。亦称藻鉴”）。辞～。～饰。\n(4)古代帝王冕上系玉的五彩丝绳玉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藻"},{"id":"glyph-kai-8611","script":"kai","character":"蘑","reading":"mó","description":"mó：〔～菇〕a.食用蕈（xùn）类，如口蘑”、松蘑”等，特指口蘑”；b.借指纠缠。c.借指拖延（菇”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蘑"},{"id":"glyph-kai-864e","script":"kai","character":"虎","reading":"hǔ","description":"hǔ：(1)哺乳动物，毛黄褐色，有黑色条纹，性凶猛，力大。骨和血及内脏均可入药（通称老虎”）～口（a.喻危险境地；b.手上拇指和食指相交的地方）。～穴（喻危险境地）。～符（古代调兵的凭证，用铜铸成虎形，分两半）。～狼（喻凶残的人）。～头蛇尾。～踞龙盘。龙腾～跃。\n(2)勇猛、威武～将。～势。～劲。～威。～～。～气。\n(3)古同唬”，威吓。\n(4)古同琥”，琥珀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虎"},{"id":"glyph-kai-864f","script":"kai","character":"虏","reading":"lǔ","description":"亦指虏掠、抄掠\n⒈俘获～获。俘～敌军万余人。\n⒉打仗时捉到的敌人优待俘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虏"},{"id":"glyph-kai-8650","script":"kai","character":"虐","reading":"nüè","description":"nüè：残暴暴～。～待。～政（暴政）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虐"},{"id":"glyph-kai-8651","script":"kai","character":"虑","reading":"lǜ；lv","description":"用绳结缀\n今子有\n⒈打算，思考，谋划考～。深思熟～。深谋远～。\n⒉担忧忧～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虑"},{"id":"glyph-kai-865a","script":"kai","character":"虚","reading":"xū","description":"xū：(1)空～无。～实。～度。～名。～左（尊敬地空出左边的座位，古代以左为尊）。空～。乘～而入。\n(2)不真实的～伪。～假（jiǎ）。～妄。～惊。～夸。～构。～传。～张声势。\n(3)内心怯懦做贼心～。\n(4)不自满～心。谦～。～怀若谷（喻对人十分谦虚）。\n(5)抽象的～词。\n(6)衰弱～弱。～胖。～汗。～脱。气～。血～。\n(7)星名，二十八宿之一。\n(8)古同墟”，大丘。\n(9)古同圩”，集市。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虚"},{"id":"glyph-kai-866b","script":"kai","character":"虫","reading":"chóng","description":"虫 chóng昆虫和类似昆虫的小动物。\n【虫草】子囊菌纲菌丝冬天侵入一些鳞翅目昆虫幼虫体内，使虫体变成充满菌丝的僵壳。夏季虫体长出具柄的棒形子座，故名。生于高山草原。能补肺益肾。又叫冬虫夏草。\n【虫媒花】〈生〉依靠昆虫传送花粉的花。其特征是花大，色鲜；有蜜腺和香味；花粉较大，外壁有突起或粘质；有集中成簇的花序。\n【虫瘿】〈生〉植物的幼枝嫩叶组织受昆虫刺伤及分泌物刺激，细胞加速分裂而长成的囊肿状构造。我国盛产的五倍子就是由一种蚜虫在盐肤木上形成的虫瘿。\n【虫豸】虫子。\n虫huǐ 1.毒蛇名◇写作\"虺\"。\n虫tóng 1.见\"虫虫\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虫"},{"id":"glyph-kai-8679","script":"kai","character":"虹","reading":"hóng","description":"hóng：(1)雨后天空中出现的彩色圆弧，有红、橙、黄、绿、蓝、靛、紫七种颜色。是大气中的小水珠经日光照射发生折射和反射作用而形成的，出现在和太阳相对着的方向。\n(2)指桥（因形似虹）～桥（中国古代的一种木拱桥。外形如长虹贯空。亦称飞桥”）。断～。长～卧波。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虹"},{"id":"glyph-kai-867d","script":"kai","character":"虽","reading":"suī","description":"即使…也;纵使\n仅,只\n原本,本\n你那里休夸口,你虽是一人为害,\n⒈连词。即使，纵然～然。麻雀～小，肝胆俱全。为人民的利益而死，～死犹生。会议～短，但可解决问题。\n⒉只，仅有～有。\n虽wèi 1.兽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虽"},{"id":"glyph-kai-867e","script":"kai","character":"虾","reading":"xiā","description":"动物名\n像虾一样弯曲\n满语对侍卫的称呼\n⒈节肢动物。体分头、胸、腹，外被甲壳，腹部有多个环节，生活在水里。有龙～、对～、米～等多种，都可食用。\n虾há 1.青蛙和蟾蜍的统称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虾"},{"id":"glyph-kai-8680","script":"kai","character":"蚀","reading":"shí","description":"损失;亏耗\n日月食\n⒈虫蛀东西蛀～。\n⒉损伤，亏损侵～。腐～。～本。\n⒊同\"食\n⒊\"日～。月～。\n蚀lì 1.谷名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚀"},{"id":"glyph-kai-8681","script":"kai","character":"蚁","reading":"yǐ","description":"膜翅类昆虫名。俗称蚂蚁\n酒的泡沫\n玄色\n比喻卑微;微末;小","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚁"},{"id":"glyph-kai-8682","script":"kai","character":"蚂","reading":"mǎ","description":"蚂蚁\n蚂蚁搬泰山\n蚂蚁啃骨头","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚂"},{"id":"glyph-kai-868a","script":"kai","character":"蚊","reading":"wén","description":"wén：昆虫，种类很多。雄的吸植物的汁液，雌的吸人畜的血液，有的传染疾病。幼虫称孑孓”～子。～香。～帐。聚～成雷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚊"},{"id":"glyph-kai-868c","script":"kai","character":"蚌","reading":"bàng；bèng","description":"bàng：生活在淡水里的一种软体动物，介壳长圆形，表面黑褐色，壳内有珍珠层，有的可以产出珍珠～胎（指珍珠）。\nbèng：〔～埠（bù）〕地名，在中国安徽省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚌"},{"id":"glyph-kai-8693","script":"kai","character":"蚓","reading":"yǐn","description":"yǐn：〔蚯～〕见蚯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚓"},{"id":"glyph-kai-8695","script":"kai","character":"蚕","reading":"cán","description":"蚕事。养蚕的工作\n养蚕\n蚕 cán同\"衠\"。\"衠\"的简化字。\n①昆虫名。幼虫能吐丝﹑结茧。有家蚕﹑柞蚕等。茧丝为重要的纤维资源。\n②养蚕。\n③蚕事;养蚕的工作。\n④侵蚀。\n⑤引申为侵害者。\n⑥传说蜀地开辟者蚕丛的简称。参见\"衠鴌\"。\n⑦见\"衠兒\"。\n蚕tiǎn 1.蝧蚕。蚯蚓的别名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚕"},{"id":"glyph-kai-86a3","script":"kai","character":"蚣","reading":"gōng；zhōng","description":"gōng：〔蜈～〕见蜈”。\nzhōng：〔～蝑〕即螽斯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚣"},{"id":"glyph-kai-86a4","script":"kai","character":"蚤","reading":"zǎo","description":"zǎo：(1)昆虫，赤褐色，善跳跃，寄生在人和畜的身体上，吸血液，能传染鼠疫等疾病。通称跳蚤”、虼蚤”。\n(2)古同早”。\n(3)古同爪”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚤"},{"id":"glyph-kai-86aa","script":"kai","character":"蚪","reading":"dǒu","description":"dǒu：〔蝌～〕见蝌”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚪"},{"id":"glyph-kai-86af","script":"kai","character":"蚯","reading":"qiū","description":"qiū：〔～蚓〕环节动物，身体细长柔软，生活于土中，以带有机物的土壤为食，使土壤疏松，对农作物有益。可作鱼和家禽的食饵，可入药。亦称曲蟮”、地龙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚯"},{"id":"glyph-kai-86c0","script":"kai","character":"蛀","reading":"zhù","description":"zhù：被虫子咬坏书本被虫～了。～蚀。\n〔～虫〕a.指能咬树干、衣服、书籍和粮食等的小虫，如天牛、衣鱼、米象；b.喻侵犯国家、公众利益的坏人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛀"},{"id":"glyph-kai-86c7","script":"kai","character":"蛇","reading":"shé；yí","description":"shé：爬行动物，身体细长，体上有鳞，没有四肢。种类很多，有的有毒，有的无毒。以蛙、鼠为食，大蛇亦吞食大的兽类～蜕。～行。～蝎。～足（喻多余无用的事物）。画～添足。\nyí：〔委（wēi）～〕见委2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛇"},{"id":"glyph-kai-86cb","script":"kai","character":"蛋","reading":"dàn","description":"dàn：(1)鸟、龟、蛇等生的带有硬壳的卵鸡～。蛇～。～白。～黄。\n(2)形状像蛋的脸～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛋"},{"id":"glyph-kai-86d9","script":"kai","character":"蛙","reading":"wā","description":"wā：两栖动物的一科，无尾，后肢长，前肢短，趾有蹼，善于跳跃和泅水。种类很多青～（俗称田鸡”）。牛～。～泳。～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛙"},{"id":"glyph-kai-86db","script":"kai","character":"蛛","reading":"zhū","description":"zhū：指蜘蛛”～网。～丝马迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛛"},{"id":"glyph-kai-86e4","script":"kai","character":"蛤","reading":"há；gé","description":"gé：〔～蜊〕软体动物，壳形卵圆，色淡褐，稍有轮纹，内白色，栖浅海沙中，肉可食。\n〔文～〕软体动物，略呈三角形，栖近海沙泥中，有黑白两种，幼时称棋子蛤”。\n〔～蚧〕爬行动物，土黄色，像壁虎，头大，尾部灰色，有红色斑点。中医用作强壮剂。\nhá：〔～蟆〕青蛙和蟾蜍的统称（蟆”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛤"},{"id":"glyph-kai-86ee","script":"kai","character":"蛮","reading":"mán","description":"⒈粗野，强横野～。～横。～缠。～不讲理。\n⒉愣，强悍～劲。～干。\n⒊〈方〉很，挺～好。～大。\n⒋〈古〉我国称南方的民族南～。〈引〉南，南方思彼～方。泛指少数民族北～。\n⒌边远地区～荒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛮"},{"id":"glyph-kai-86fe","script":"kai","character":"蛾","reading":"é；yǐ","description":"é：昆虫，与蝴蝶相似，体肥大，触角细长如丝，翅面灰白，静止时，翅左右平放，常在夜间活动，有趋光性～子。～眉。～扬（眉扬，形容美人笑貌）。～绿。飞～扑火。\nyǐ：古同蚁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛾"},{"id":"glyph-kai-8700","script":"kai","character":"蜀","reading":"shǔ","description":"shǔ：(1)中国四川省的别称～本（宋代在四川刻印的书籍）。～客（旅游蜀地的人）。～椒。～绣（四川出产的刺绣）。～锦。得陇望～。\n(2)中国朝代名～汉。\n(3)中国周代诸侯国名，在今四川省成都市一带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜀"},{"id":"glyph-kai-8702","script":"kai","character":"蜂","reading":"fēng","description":"fēng：(1)昆虫，会飞，多有毒刺，能蜇人。有蜜蜂”、熊蜂”、胡蜂”、细腰蜂”等多种，多成群住在一起。\n(2)特指蜜蜂”～巢。～房。～蜡。～蜜。～乳。～王（生殖器官发育完全的雌蜂，专司产卵，通常每个蜂群只有一只。亦称母蜂”）。～腰（a.蜂腰中间细，喻居中者最差；b.诗律八病”之一；c.书法笔病之一）。\n(3)众多～起。～拥。～聚。～集。\n〔～鸟〕鸟类中最小的一种，大小如大拇指，嘴细长。吃花蜜和花上的小昆虫。产于南美洲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜂"},{"id":"glyph-kai-8708","script":"kai","character":"蜈","reading":"wú","description":"wú：〔～蚣〕节肢动物，由许多环节构成，每节有脚一对，头部的脚像钩子，能分泌毒液，捕食小虫，中医入药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜈"},{"id":"glyph-kai-8712","script":"kai","character":"蜒","reading":"yán","description":"yán：〔～蚰〕即蛞喻”。\n〔蚰～〕见蚰”。\n〔蜿～〕见蜿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜒"},{"id":"glyph-kai-8713","script":"kai","character":"蜓","reading":"tíng","description":"tíng：〔蜻（qīng）～〕见蜻1”。\n〔??～〕见蝘”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜓"},{"id":"glyph-kai-8715","script":"kai","character":"蜕","reading":"tuì","description":"tuì：(1)蝉或蛇等脱下来的皮蛇～。蝉～。\n(2)蛇、蝉等动物脱皮～皮。\n(3)鸟换毛。\n(4)解脱，变化～化。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜕"},{"id":"glyph-kai-8717","script":"kai","character":"蜗","reading":"wō","description":"动物名,蜗牛\n蜗luó 1.见\"蜗醢\"﹑\"蜗旋\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜗"},{"id":"glyph-kai-8718","script":"kai","character":"蜘","reading":"zhī","description":"zhī：〔～蛛〕节肢动物，身体圆形或长圆形，分头胸和腹两部，有触须和脚四对。肛门分泌的黏液凝成细丝，用来结网捕食昆虫。通称蛛蛛”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜘"},{"id":"glyph-kai-871c","script":"kai","character":"蜜","reading":"mì","description":"mì：(1)蜜蜂采取花的甜汁酿成的东西蜂～。～饯。～供（把油炸的短面条拌上蜜或糖制成的糕点）。～源（指能大量供蜜蜂采蜜的植物）。～丸。\n(2)甜美甜言～语。口～腹剑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜜"},{"id":"glyph-kai-8721","script":"kai","character":"蜡","reading":"là","description":"动物、矿物或植物所产生的油质,具有可塑性,能燃能熔,不溶于水,是一羟基醇或固醇的脂肪酸酯\n蜡烛的简称\n用蜡涂抹\n⒈动、植、矿物所产生的一种油质，易熔化，具有可塑性，不溶于水蜂～。白～。石～。\n⒉蜡烛的简称拿支～来。\n⒊色淡黄像蜡的～黄。～梅。\n⒈〈古〉夏历年终的一种祭祀～祭。\n蜡qù 1.蝇蛆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜡"},{"id":"glyph-kai-873b","script":"kai","character":"蜻","reading":"qīng","description":"qīng：〔～蜓〕昆虫，捕食小飞虫，是益虫。幼虫称水虿”，生活在水中（有的地区称蚂螂”），如～～点水”（喻做事肤浅不深入）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜻"},{"id":"glyph-kai-8747","script":"kai","character":"蝇","reading":"yíng","description":"多指苍蝇。动物名。属昆虫类中的双翅类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝇"},{"id":"glyph-kai-8749","script":"kai","character":"蝉","reading":"chán","description":"古代一种极薄的丝织品。以其薄如蝉翼而得名\n连续不断\n蝉 chán同翅目昆虫。种类很多，雄的腹部有发音器，能连续不断发出尖锐的声音。幼虫生活在土里。俗称知了。\n【蝉联】连续不断～羽毛球女子单打世界冠军。\n【蝉蜕】\n①〈生〉蝉的幼虫变为成虫时蜕下的壳。中医用作解热镇静的药物。又叫蝉衣。\n②比喻解脱。\n【蝉衣】见【蝉蜕】。\n⒈昆虫。俗叫\"知了\"。雄的腹部有发音器，鸣声高大。幼虫在土中生活。蚱蝉的蜕壳叫\"蝉蜕\"或\"蝉衣\"，可供药用。\n蝉tí 1.黏蝉，汉代县名。在今朝鲜境内。\n蝉shàn 1.见\"蜿蝉\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝉"},{"id":"glyph-kai-874c","script":"kai","character":"蝌","reading":"kē","description":"kē：〔～蚪〕蛙或蟾蜍的幼体，黑色，身体椭圆，有长尾，生活在水中，最后变成蛙或蟾蜍。亦称活东”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝌"},{"id":"glyph-kai-874e","script":"kai","character":"蝎","reading":"xiē","description":"xiē：节肢动物，胎生。头胸部的螯肢呈钳状，胸脚四对◇腹狭长，末端有毒钩，用来防敌和捕虫，食昆虫、蜘蛛等。干燥虫体可入药～子。毒如蛇～。\n〔～虎〕即壁虎”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝎"},{"id":"glyph-kai-8757","script":"kai","character":"蝗","reading":"huáng","description":"huáng：〔～虫〕昆虫，种类很多，躯体绿色或黄褐色。咀嚼式口器，后足适于弹跳，常常成群飞翔，是农业害虫，亦称蚂（mà）蚱”；简称蝗”，如～灾”，灭～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝗"},{"id":"glyph-kai-8759","script":"kai","character":"蝙","reading":"biān","description":"biān：〔～蝠〕哺乳动物，头和身体的样子像老鼠。前后肢都有薄膜和身体连着，夜间在空中飞，捕食蚊蛾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝙"},{"id":"glyph-kai-8760","script":"kai","character":"蝠","reading":"fú","description":"fú：〔蝙～〕见蝙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝠"},{"id":"glyph-kai-8774","script":"kai","character":"蝴","reading":"hú","description":"hú：〔～蝶〕见蝶”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝴"},{"id":"glyph-kai-8776","script":"kai","character":"蝶","reading":"dié","description":"dié：〔蝴～〕昆虫，翅膀阔大，颜色美丽，静止时四翅竖立在背部，吸花蜜，种类很多，亦作胡蝶”；简称蝶”，如彩～”，～骨”（人的头骨之一），～泳”（游泳的一种姿势，亦是游泳项目之一，形似蝶飞）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝶"},{"id":"glyph-kai-8783","script":"kai","character":"螃","reading":"páng","description":"páng：〔～蟹〕见蟹”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螃"},{"id":"glyph-kai-878d","script":"kai","character":"融","reading":"róng","description":"róng：(1)固体受热变软或化为流体～化。～解。消～。\n(2)调合，和谐～合。～洽。～汇贯通。其乐～～。\n(3)流通～泄（飘动，浮动）。金～（货币的流通，即储蓄，信贷、汇兑、股票和证券交易等经济活动的总称）。\n(4)长远、永久～裔（形容声调悠长）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-融"},{"id":"glyph-kai-87ba","script":"kai","character":"螺","reading":"luó","description":"luó：(1)软体动物，体外包着锥形、纺锤形或椭圆形的硬壳，上有旋纹～蛳。田～。～。～号。～钿。法～（用海螺壳做成的佛教乐器）。\n(2)像螺壳纹理的～纹。～旋。～钉。～母。～栓。～髻（古代妇女似螺壳的发形）。\n(3)同脶”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螺"},{"id":"glyph-kai-87c0","script":"kai","character":"蟀","reading":"shuài","description":"shuài：〔蟋～〕见蟋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟀"},{"id":"glyph-kai-87c6","script":"kai","character":"蟆","reading":"má","description":"m：〔蛤（há）～〕见蛤2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟆"},{"id":"glyph-kai-87cb","script":"kai","character":"蟋","reading":"xī","description":"xī：〔～蟀〕昆虫，身体黑褐色，触角长，善于跳跃。雄性好斗，两翅摩擦能发声，对农作物有害。亦称促织”、趋织”；俗称蛐蛐儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟋"},{"id":"glyph-kai-87f9","script":"kai","character":"蟹","reading":"xiè","description":"xiè：〔螃～〕节肢动物，水陆两栖。全身有甲壳，足有五对，前双足成钳状，称螯”，横着爬。腹部分节，俗称脐”，雄性脐呈长尖形，雌性脐呈椭圆形。简称蟹”，如河～”，海～”，～黄”，～青”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟹"},{"id":"glyph-kai-8815","script":"kai","character":"蠕","reading":"rú","description":"rú：像蚯蚓那样慢慢地爬动～动。～～。～形动物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠕"},{"id":"glyph-kai-8822","script":"kai","character":"蠢","reading":"chǔn","description":"chǔn：(1)愚笨，笨拙～人。～材。～话。～事。～然。～拙。～笨。\n(2)虫子蠕动～动。～～。～～欲动（指坏人伺机欲动或敌人准备进犯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠢"},{"id":"glyph-kai-8840","script":"kai","character":"血","reading":"xuè；xie","description":"xuè：(1)人或动物体内循环系统的不透明液体，大多为红色，主要成分为血浆”、血细胞”和血绣”。味咸而腥～型。～脂。～压。～糖。～迹。～汗。～泪。～洗。～书。～雨腥风。～海深仇。\n(2)人类因生育而自然形成的关系～统。～缘。\n(3)喻刚强热烈～性。～气方刚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-血"}];
